from werkzeug.datastructures import Headers


def create_headers(defaults: list[list[str]] | None = None) -> dict[str, list[str]]:
    """Create a new headers object with optional initial values. defaults: An array of header key-value pairs to initialize the Headers object with, e.g. [['Content-Type', 'application/json']] -> {"Content-Type": ["application/json"]}."""
    try:
        headers = Headers(defaults)
        # Convert to a dict of lists to match expected JSON format
        result = {}
        current_key = None
        current_values = []

        for key, value in headers:
            if key != current_key:
                if current_key is not None:
                    result[current_key] = current_values
                current_key = key
                current_values = [value]
            else:
                current_values.append(value)

        if current_key is not None:
            result[current_key] = current_values

        return result
    except Exception as e:
        raise ValueError(f"Failed to create headers: {str(e)}")
