from werkzeug.datastructures import Authorization
from werkzeug.http import parse_dict_header
import base64
import binascii


def parse_authorization_header(value: str | None) -> dict[str, str | None] | None:
    """Parse an Authorization header value and create an Authorization object.

    Args:
        value: The header value to parse, e.g. "Basic dXNlcjpwYXNz"

    Returns:
        A dictionary with the authorization type and data, or None if empty.
        Example: {"auth_type": "basic", "data": {"username": "user", "password": "pass"}}
    """
    if not value:
        return None

    try:
        auth_obj = Authorization.from_header(value)
        if auth_obj is None:
            return None

        result = {"auth_type": auth_obj.auth_type}

        if auth_obj.data:
            result["data"] = auth_obj.data
        if auth_obj.token:
            result["token"] = auth_obj.token

        return result
    except Exception as e:
        raise ValueError(f"Failed to parse authorization header: {str(e)}")
