def parse_options_header(value: str | None) -> dict[str, str | dict[str, str]]:
    """Parse a header that consists of a value with key=value parameters separated by semicolons. For example, the Content-Type header.

    Example:
        parse_options_header("text/html; charset=UTF-8") -> {"value": "text/html", "options": {"charset": "UTF-8"}}
