        # Convert ImmutableMultiDict to a dict[str, str] for JSON serialization
        # Since each cookie key maps to a single value, we take the first value
        return {key: values[0] if values else "" for key, values in result.items()}
    except Exception as e:
        raise ValueError(f"Failed to parse cookies: {str(e)}")
