from werkzeug import Request


def create_request(path: str, method: str | None = None, headers: dict[str, str] | None = None, data: dict[str, str] | None = None) -> dict[str, str | int | list[str] | dict[str, str] | None]:
    """Create a new request object from provided values. path: The path of the request, e.g. '/api/users' -> request object with path '/api/users'. method: The HTTP method of the request, e.g. 'GET', 'POST' -> request object with specified method. headers: HTTP headers as key-value pairs, e.g. {'Content-Type': 'application/json'} -> request object with headers. data: Form data or JSON payload, e.g. {'name': 'John'} -> request object with form data."""
    try:
        request = Request.from_values(
            path=path,
            method=method,
            headers=headers,
            data=data
        )
        return {
            "path": request.path,
            "method": request.method,
            "headers": dict(request.headers),
            "data": request.get_data(as_text=True) if request.get_data() else None
        }
    except Exception as e:
        raise ValueError(f"Failed to create request: {str(e)}")
