from werkzeug.datastructures import ETag


def parse_etag(value: str) -> dict[str, str | bool] | None:
    """Parse a quoted ETag value and create an instance of the ETag class, or None if the value is empty or invalid. value: The ETag value to parse, e.g. '\"foo\"' -> {'value': 'foo', 'weak': False}."""
    try:
        etag = ETag.from_header(value)
        if etag is None:
            return None
