def parse_range(value: str) -> dict[str, str | list[dict[str, int | None]]] | None:
    """Parse a ``Range`` header value and create an instance of this class, or ``None`` if the value is empty.

    Args:
        value (str): The Range header value to parse, e.g. "bytes=0-100"

    Returns:
        dict with keys "units" (str) and "ranges" (list of dicts with "start" and "end" int|None),
        or None if value is empty or invalid.
