def check_if_response_is_json(content_type: str) -> bool:
    """Check if the Content-Type header indicates JSON data, either 'application/json' or 'application/*+json'. content_type: The Content-Type header value of the response, e.g. 'application/json' -> true."""
    if not isinstance(content_type, str):
