from time import mktime
from typing import Union, Optional


def _dt_as_utc(d: dt.datetime) -> dt.datetime:
    """Convert a timezone-aware datetime to UTC if it isn't already."""
    if d.tzinfo is None:
        # Assume naive datetime is in UTC
        return d.replace(tzinfo=dt.timezone.utc)
    return d.astimezone(dt.timezone.utc)


def format_http_date(timestamp: Optional[str] = None) -> str:
    """Format a datetime object or timestamp into an RFC 2822 date string.

    Args:
        timestamp (str, optional): The datetime or timestamp to format. Defaults to the current time.

    Returns:
        str: An RFC 2822 formatted date string.

    Example:
        >>> format_http_date("2023-01-01")
        'Sun, 01 Jan 2023 00:00:00 GMT'
    """
    if timestamp is None:
        # Use current time
        timestamp = dt.datetime.now(dt.timezone.utc)
    else:
        # Try to parse the timestamp as a datetime
        try:
            # First try to parse as datetime string
            if isinstance(timestamp, str):
                # Try common datetime formats
                for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%Y-%m-%dT%H:%M:%S"):
                    try:
                        parsed = dt.datetime.strptime(timestamp, fmt)
                        break
                    except ValueError:
                        continue
                else:
                    # If no format matches, try parsing as timestamp
                    try:
                        parsed = dt.datetime.fromtimestamp(float(timestamp), tz=dt.timezone.utc)
                    except ValueError:
                        raise ValueError(f"Invalid timestamp format: {timestamp!r}")
            else:
                parsed = timestamp
        except Exception as e:
            raise ValueError(f"Invalid timestamp: {timestamp!r}") from e

        timestamp = parsed

    # Handle different types of timestamp inputs
    if isinstance(timestamp, dt.date):
        if not isinstance(timestamp, dt.datetime):
            # Assume plain date is midnight UTC
            timestamp = dt.datetime.combine(timestamp, dt.time(), tzinfo=dt.UTC)
        else:
            # Ensure datetime is timezone-aware
            timestamp = _dt_as_utc(timestamp)

        return email.utils.format_datetime(timestamp, usegmt=True)

    if hasattr(timestamp, 'tm_year'):
        # It's a struct_time
        timestamp = mktime(timestamp)

    return email.utils.formatdate(timestamp, usegmt=True)
